import { readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(scriptDir, "..");
const require = createRequire(import.meta.url);
const Babel = require(resolve(projectRoot, "vendor/babel.min.js"));
const sourceFiles = ["data.jsx", "primitives.jsx", "screens.jsx", "app.jsx"];

const compiled = [];
for (const file of sourceFiles) {
  const source = await readFile(resolve(projectRoot, file), "utf8");
  const output = Babel.transform(source, {
    filename: file,
    presets: [
      ["env", { modules: false, targets: { chrome: "74", android: "9" } }],
      ["react", { runtime: "classic" }],
    ],
    comments: false,
    compact: false,
    sourceMaps: false,
  }).code;
  compiled.push(`/* ${file} */\n(() => {\n${output}\n})();`);
}

const banner = "/* 今刻 1.0 WebView bundle — generated by scripts/build-web-bundle.mjs */\n";
await writeFile(resolve(projectRoot, "app-bundle.js"), banner + compiled.join("\n\n") + "\n", "utf8");
console.log(`WEB_BUNDLE_READY=${resolve(projectRoot, "app-bundle.js")}`);
